 if(a.pointer===null){const g=mouseGround(),d=g?Math.hypot(p.x-g.x,p.z-g.z):0;a.aim=g&&d>.5?{angle:Math.atan2(p.x-g.x,p.z-g.z),power:(d-b.aimMin)/(b.aimMax-b.aimMin)}:{angle:player.aim,power:.5};}
