function arenaBanner(){if(typeof document.createElement!=='function')return;const a=arenas[activeArena],node=document.createElement('div');node.className='arena-banner';node.innerHTML=`<small>${a.tag}</small><strong>${a.name}</strong><i></i>`;const show=()=>(gameUI??app).append(node);if(gameUI)requestAnimationFrame(()=>requestAnimationFrame(show));else show();node.addEventListener?.('animationend',e=>{if(e.target===node)node.remove();});setTimeout(()=>node.remove?.(),8000);}
function toast(message:string,seconds=1){document.querySelector('#combatToast')!.textContent=message;toastTimer=seconds;}
// Mirrored pairs share a kind, so each half holds 2 repair, 2 double-damage, 2 speed and 2 shield spots, never two of a kind in a row.
/** Pickup effects: repair HP, double-damage and speed-boost seconds, speed multiplier, shield HP (extra hull on top of max HP), respawn seconds. */
const PICKUP={repair:60,power:20,boost:8,speed:1.35,shield:60,respawn:14};
const pickupColors=[0x5fe2a0,0xff6846,0xffd24a,0x5cc8ff];
const pickupShape=(kind:number)=>kind===2?new THREE.ConeGeometry(.62,1.4,4):kind===3?new THREE.IcosahedronGeometry(.75):new THREE.OctahedronGeometry(.8);
const pickupLabel=(kind:number)=>[tr('＋ 维修','+ Repair'),tr('2× 伤害','2× damage'),tr('⚡ 加速','⚡ Speed'),tr('◆ 护盾','◆ Shield')][kind];
// A pale blue bubble shows a car's pickup shield until it is shot away.
const shieldBubbles=new Map<Car,THREE.Mesh>();const bubbleMaterial=new THREE.MeshBasicMaterial({color:0x7fd2ff,transparent:true,opacity:.18,depthWrite:false});
function updateShieldBubbles(){for(const c of cars){let b=shieldBubbles.get(c);const on=c.alive&&(c.shield??0)>0;if(!b){if(!on)continue;b=new THREE.Mesh(new THREE.SphereGeometry(1,20,14),bubbleMaterial);b.scale.set(vehicles[c.loadout].hx*1.6,1.5,vehicles[c.loadout].hz*1.35);scene.add(b);shieldBubbles.set(c,b);}b.visible=on&&c.mesh.visible;if(on){b.position.copy(c.mesh.position).add(new THREE.Vector3(0,.9,0));b.rotation.y=c.angle;b.scale.set(vehicles[c.loadout].hx*1.6,1.5,vehicles[c.loadout].hz*1.35);}}}
const pickups=PICKUP_SPOTS.map(([x,z,kind])=>{const material=new THREE.MeshBasicMaterial({color:pickupColors[kind]});const mesh=new THREE.Mesh(pickupShape(kind),material);mesh.position.set(x,terrainHeight(x,z)+1.2,z);scene.add(mesh);return {x,z,kind,mesh,timer:0};});
// ---- Vehicle skills. Rules and numbers live in ./skills, meshes in ./skill-effects.
type SkillState={cloak:number;ambush:number;slow:number;overdrive:number;still:number;stacks:number;stackTarget:Car|null;stackTimer:number;ramCd:number;aura:number;dome:{fx:Dome;ttl:number;absorbed:number}|null};
const ST=skillTuning,skillStates=new Map<Car,SkillState>(),skillFx=new SkillEffects(scene),aimIndicator=new AimIndicator(scene,(x,z)=>driveHeight(x,z,player.mesh.position.y),8);
const hooks:{owner:Car;target:Car|null;cable:Cable;phase:'out'|'pull'|'back';t:number;end:THREE.Vector3}[]=[];
