 document.querySelectorAll<HTMLInputElement|HTMLSelectElement>('[data-setting]').forEach(el=>{const key=el.dataset.setting as keyof typeof d.settings;if(el instanceof HTMLInputElement&&el.type==='checkbox')el.checked=!!d.settings[key];else el.value=String(d.settings[key]);});for(const key of ['sensitivity','controlScale','volume','music','zoom'] as const)document.querySelector(`#${key}Out`)!.textContent=String(d.settings[key]);document.querySelectorAll<HTMLInputElement>('input.slider').forEach(el=>el.style.setProperty('--fill',`${(Number(el.value)-Number(el.min))/(Number(el.max)-Number(el.min))*100}%`));document.querySelectorAll<HTMLElement>('[data-choice]').forEach(group=>group.querySelectorAll<HTMLElement>('[data-value]').forEach(b=>b.classList.toggle('selected',String(d.settings[group.dataset.choice as 'quality'|'difficulty'])===b.dataset.value)));document.querySelector('#qualityNote')!.textContent={low:tr('低分辨率，关闭动态阴影，最省电','Lower resolution, no dynamic shadows, best battery life'),medium:tr('推荐：画质与帧率平衡','Recommended: balance of looks and frame rate'),high:tr('高分辨率、动态阴影与环境光遮蔽','High resolution, dynamic shadows and ambient occlusion')}[d.settings.quality];document.querySelectorAll<HTMLElement>('[data-lang]').forEach(b=>b.classList.toggle('selected',b.dataset.lang===lang));document.querySelectorAll<HTMLElement>('#playChoice [data-play]').forEach(b=>b.classList.toggle('selected',b.dataset.play===playChoice));{const note=document.querySelector('#playNote');if(note)note.textContent=tr(`本机识别为：${deviceName(detectedPlay)} · 当前使用：${deviceName(mobileMode?'mobile':'web')}`,`This device looks like: ${deviceName(detectedPlay)} · In use: ${deviceName(mobileMode?'mobile':'web')}`);}document.querySelector('#difficultyNote')!.textContent={easy:tr('敌车伤害与血量降低，适合熟悉操作','Enemies deal less damage and have less health; good for learning'),normal:tr('标准平衡','Standard balance'),hard:tr('敌车更耐打、伤害更高','Enemies are tougher and hit harder')}[d.settings.difficulty];document.querySelectorAll<HTML