function applySettings(){const settings=profileStore.data.settings;sound.setVolume(settings.volume);sound.setMusicVolume(settings.music);app.style.setProperty('--control-scale',String(settings.controlScale));renderer.setPixelRatio(Math.min(devicePixelRatio,settings.quality==='high'?2:settings.quality==='medium'?1.3:1));renderer.shadowMap.enabled=settings.quality!=='low';pipeline?.setQuality(settings.quality);combatEffects.setLights(settings.quality!=='low');resize();}
app.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest<HTMLElement>('button');if(!button||running)return;if(button.dataset.lang){if(saveLang(button.dataset.lang as Lang))reloadForLanguage({driver,page:activePage});return;}if(button.dataset.play){menuSound();playChoice=button.dataset.play as PlayChoice;savePlayChoice(playChoice);applyPlayMode(resolvePlayMode(playChoice));renderUI();return;}if(button.dataset.quick){menuSound();if(button.dataset.quick==='manual'){showPage('settings');const node=document.querySelector<HTMLElement>('.field-manual');node?.scrollIntoView({block:'center',behavior:'smooth'});node?.classList.remove('spotlight');void node?.offsetWidth;node?.classList.add('spotlight');}else showPage(button.dataset.quick);return;}if(button.id==='nextStep'){if(activePage==='garage'&&!profileStore.carUnlocked(selectedCar)&&!profileStore.trialAvailable(selectedCar)){menuSound('deny');menuToast(tr(`这辆车 LEVEL ${carLock(selectedCar)} 解锁，今天的试驾已用完`,`This car unlocks at LEVEL ${carLock(selectedCar)}; today's test drive is used up`));return;}if(activePage==='battle'&&!profileStore.modeUnlocked(selectedMode)){menuSound('deny');menuToast(tr(`该模式 LEVEL ${modeLock(selectedMode)} 开放`,`This mode opens at LEVEL ${modeLock(selectedMode)}`));return;}menuSound();showPage(activePage==='garage'?'armory':activePage==='armory'?'battle':activePage==='battle'?'arena':activePage==='result'?'battle':'garage');return;}if(button.id==='prevStep'){menuSound();showPage(activePage==='arena'?'battle':activePage==='battle'?'armory':'garage');return;}if(button.id==='rerollTerrain'){menuSound('reroll');rollTerrain(true);fx.pop(button);return;}if(button.dataset.cycle){selectCar((selectedCar+Number(button.dataset.cycle)+vehicles.length)%vehicles.length);return;}if(button.dataset.tab){tuneTab=button.dataset.tab;menuSound();renderUI();return;}if(button.dataset.value&&button.parentElement?.dataset.choice){const key=button.parentElement.dataset.choice as 'quality'|'difficulty';(profileStore.data.settings as Record<string,unknown>)[key]=button.dataset.value;menuSound();profileStore.save();renderUI();return;}if(button.dataset.variantPick!==undefined){fx.pop(button);if(!profileStore.setVariant(selectedCar,Number(button.dataset.variantPick))){menuSound('deny');menuToast(tr('该型号尚未解锁','This variant is still locked'));renderUI();return;}menuSound('weapon');renderUI();return;}if(progressionClick(button))return;if(button.dataset.nav){menuSound();showPage(button.dataset.nav);}else if(button.dataset.upgrade){const kind=button.dataset.upgrade;if(profileStore.upgrade(selectedCar,kind as Upgrade)){menuSound('upgrade');renderUI();const card=document.querySelector<HTMLElement>(`.upgrade-card[data-kind="${kind}"]`);fx.burst(card);fx.float(card,[tr('装甲 +8%','Armour +8%'),tr('极速 +3%','Speed +3%'),tr('伤害 +4%','Damage +4%')][['armor','engine','weapon'].indexOf(kind)]);card?.querySelector('.pips i.on:last-of-type')?.classList?.add('fresh');fx.coins();}else{menuSound('deny');menuToast(tr('升级未完成：信用点或零件不足、车辆未解锁或已满级','Upgrade failed: not enough credits or parts, vehicle locked, or already maxed'));renderUI();}}else if(button.dataset.weapon!==undefined){selectedCar=Number(button.dataset.weapon);profileStore.data.car=selectedCar;profileStore.data.weapon=vehicles[selectedCar].weapon;profileStore.save();renderUI();}else if(button.dataset.arena!==undefined){if(!profileStore.arenaUnlocked(Number(button.dataset.arena))){menuSound('deny');fx.pop(button);menuToast(tr(`该地图 LEVEL ${arenaLock(Number(button.dataset.arena))} 开放`,`This arena opens at LEVEL ${arenaLock(Number(button.dataset.arena))}`));return;}selectedArena=Number(button.dataset.arena);menuSound('arena');fx.pop(button);profileStore.data.arena=selectedArena;profileStore.save();renderUI();}else if(button.dataset.claim){const card=button.closest<HTMLElement>('.milestone');if(profileStore.claim(button.dataset.claim)){menuSound();fx.burst(card);fx.coins();menuToast(tr('里程碑奖励已领取','Milestone reward claimed'));}renderUI();}});
app.addEventListener('input',event=>{const input=event.target as HTMLInputElement,key=input.dataset.setting;if(!key)return;const d=profileStore.data.settings;if(key==='volume'||key==='music'||key==='sensitivity'||key==='controlScale'||key==='zoom')d[key]=Number(input.value);else if(key==='shake')d.shake=input.checked;else if(key==='quality')d.quality=input.value as typeof d.quality;else if(key==='difficulty')d.difficulty=input.value as typeof d.difficulty;profileStore.save();renderUI();});
