{let dragX:number|null=null;overlay.addEventListener('pointerdown',e=>{if((e.target as HTMLElement).closest('button,input,select,aside,.vehicle-strip,.glass-panel'))return;dragX=e.clientX;});addEventListener('pointermove',e=>{if(dragX===null)return;showroom?.nudge((e.clientX-dragX)*.02);dragX=e.clientX;});addEventListener('pointerup',()=>dragX=null);}

