function escapeHTML(text:string){return text.replace(/[&<>"']/g,c=>`&#${c.charCodeAt(0)};`);}
/** Career-page table of every driver saved in this browser; the current driver is highlighted. */
function renderLocalBoard(){const board=document.querySelector('#localBoard');if(!board)return;const rows=localDrivers();board.innerHTML=rows.length?`<div class="lb-row lb-head"><span>#</span><span>${tr('车手','Driver')}</span><span>${tr('胜场','Wins')}</span><span>${tr('对局','Matches')}</span><span>${tr('击毁','Kills')}</span><span>${tr('最高积分','Best score')}</span></div>`+rows.map((r,i)=>`<div class="lb-row${r.name===driver?' me':''}"><span>${i+1}</span><span>${escapeHTML(r.name)}</span><span>${r.wins}</span><span>${r.games}</span><span>${r.kills}</span><span>${r.best}</span></div>`).join(''):`<p class="lb-empty">${tr('完成一场对局后会出现在这里','Finish a match to appear here')}</p>`;}
const issuesURL='https://github.com/ZixunHuangUPenn/Arena-Wreckers/issues/new';
document.querySelector('#publishWins')!.addEventListener('click',()=>{
 const params=new URLSearchParams({title:'Arena Wreckers · 胜场记录',body:JSON.stringify({driver,wins:profileStore.data.wins})});
 window.open(issuesURL+'?'+params,'_blank','noopener');
});
document.querySelector('#readWins')!.addEventListener('click',async()=>{
 const list=document.querySelector('#winsList')!;
 list.textContent=tr('正在读取…','Loading…');
 try{
  const best=new Map<string,{name:string;wins:number}>();
  for(let page=1;;page++){
   const response=await fetch('https://api.github.com/repos/ZixunHuangUPenn/Arena-Wreckers/issues?state=all&per_page=100&page='+page);
   if(!response.ok)throw Error();
   const issues=await response.json();
   for(const issue of issues){
    if(issue.pull_request||issue.title!=='Arena Wreckers · 胜场记录')continue;
    try{const {driver:name,wins}=JSON.parse(issue.body);
     if(typeof name==='string'&&name.trim()&&Number.isSafeInteger(wins)&&wins>=0&&wins>(best.get(issue.user.login+'\n'+name.trim().slice(0,24))?.wins??-1))best.set(issue.user.login+'\n'+name.trim().slice(0,24),{name:name.trim().slice(0,24),wins});
    }catch{}
   }
   if(issues.length<100)break;
  }
  list.textContent=[...best.entries()].sort((a,b)=>b[1].wins-a[1].wins).map(([key,p],i)=>(i+1)+'. '+p.name+' (@'+key.split('\n')[0]+') · '+p.wins+tr(' 胜',' wins')).join('\n')||tr('还没有公开记录','No public records yet');
 }catch{list.textContent=tr('排行榜暂时无法读取，请稍后重试','The leaderboard could not be read. Try again later.');}
});
